Use the `pg` library's `Pool` class — it handles connection pooling natively:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT ?? '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                  // max connections in pool
  min: 2,                   // keep this many idle connections open

  // Timeouts (milliseconds)
  connectionTimeoutMillis: 5000,   // fail fast if no connection available
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  query_timeout: 10000,            // per-query timeout
  statement_timeout: 10000,        // server-side query timeout (PostgreSQL 9.6+)
});

// Surface pool errors so they don't crash the process silently
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
});
```

**Query helper with automatic release:**

```javascript
export async function query(sql, params) {
  const start = Date.now();
  try {
    const result = await pool.query(sql, params);
    return result;
  } catch (err) {
    // Attach query context to the error for easier debugging
    err.query = sql;
    throw err;
  } finally {
    // pool.query() auto-releases — only needed if you called pool.connect()
  }
}
```

**For transactions** (where you need to hold a single connection):

```javascript
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();  // always release, even on error
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Graceful shutdown** (important for containers/serverless):

```javascript
process.on('SIGTERM', async () => {
  await pool.end();
  process.exit(0);
});
```

Key points:
- `connectionTimeoutMillis` prevents your app from hanging when the DB is unreachable — set it low (2–5s) in production
- Always `release()` clients from `pool.connect()` in a `finally` block — leaking clients will exhaust the pool
- `statement_timeout` is enforced server-side, so it catches runaway queries even if the Node process hangs
- `max: 20` is a safe default; tune down if your Postgres `max_connections` is low (check with `SHOW max_connections`)
